import { buildCard } from "./engine";
import { PROFILES, syntheticAthlete } from "./fixtures";
import type { PlayerCard } from "@/types/player";

/**
 * The three showcase cards (Silver, Gold, Icon) used on the home page and in
 * the site's link preview, generated by the real engine from synthetic athletes.
 */
export function demoCards(now = new Date()): [PlayerCard, PlayerCard, PlayerCard] {
  const card = (profile: keyof typeof PROFILES, name: string): PlayerCard => {
    const built = buildCard(syntheticAthlete(PROFILES[profile], now), now);
    // Only the card face is drawn: drop the calendar series it doesn't need.
    return {
      ...built,
      displayName: name,
      name,
      country: null,
      inputs: { ...built.inputs, daily: { ...built.inputs.daily, minutes: [], prs: [] }, races: [] },
    };
  };
  return [card("dedicatedRunner", "PACER"), card("triathlete", "IRONMAN"), card("eliteMountainRunner", "SUMMIT")];
}
